insert into public.books (id, name, short_name, chapters, testament, icon, color, order_index, description, active) values
  ('oseias', 'Oséias', 'OSÉIAS', 14, 'Antigo Testamento', '💧', '#38bdf8', 1, 'O profeta do amor fiel de Deus: casamento com Gômer, chamado ao arrependimento e promessas de restauração para Israel.', true),
  ('obadias', 'Obadias', 'OBADIAS', 1, 'Antigo Testamento', '🦅', '#fbbf24', 2, 'O menor livro do Antigo Testamento: a visão contra Edom, o Dia do Senhor e a certeza de que o reino será do Senhor.', true),
  ('jonas', 'Jonas', 'JONAS', 4, 'Antigo Testamento', '🐋', '#34d399', 3, 'O profeta fujão: a tempestade, o grande peixe, o arrependimento de Nínive e a lição da misericórdia de Deus.', true)
on conflict (id) do update set
  name = excluded.name, short_name = excluded.short_name, chapters = excluded.chapters,
  testament = excluded.testament, icon = excluded.icon, color = excluded.color,
  order_index = excluded.order_index, description = excluded.description, active = excluded.active;

