-- ---------------------------------------------------------------------------
-- CONFERÊNCIA
-- ---------------------------------------------------------------------------
select b.id as livro, b.name,
  count(*) filter (where q.difficulty = 'facil')   as faceis,
  count(*) filter (where q.difficulty = 'medio')   as medias,
  count(*) filter (where q.difficulty = 'dificil') as dificeis,
  count(*) as total
from public.books b join public.questions q on q.book_id = b.id
where b.active and q.active group by b.id, b.name order by b.order_index;
